$ErrorActionPreference='Stop';$Run='C:\Users\aaron\Desktop\URAP\artifacts\detached_aot_action_memory_target_v86';$StatePath=Join-Path $Run 'state.json';if(-not(Test-Path $StatePath)){Write-Host 'status: NOT RUNNING';Write-Host 'done/total: 0/7';exit 0};$State=Get-Content $StatePath -Raw|ConvertFrom-Json;$P=Get-CimInstance Win32_Process -Filter "ProcessId=$($State.pid)" -ErrorAction SilentlyContinue;$Progress=if(Test-Path $State.progress){Get-Content $State.progress -Raw|ConvertFrom-Json}else{$null};$Child=if($Progress.child_pid){Get-CimInstance Win32_Process -Filter "ProcessId=$($Progress.child_pid)" -ErrorAction SilentlyContinue}else{$null};$Paths=@($State.stdout,$State.stderr,$State.progress)|Where-Object{Test-Path $_};$Latest=$Paths|ForEach-Object{Get-Item $_}|Sort-Object LastWriteTime -Descending|Select-Object -First 1;Write-Host ('status: '+$(if($P){'RUNNING'}else{'NOT RUNNING'}));Write-Host ('done/total: '+$(if($Progress){"$($Progress.done)/$($Progress.total)"}else{'0/7'}));Write-Host ('stage: '+$(if($Progress){$Progress.stage}else{'starting'}));Write-Host "pid: $($State.pid)";Write-Host "start_time: $($State.start_time)";if($P){Write-Host "command: $($P.CommandLine)"};if($Child){Write-Host "child_pid: $($Child.ProcessId)"};Write-Host ('last_output_timestamp: '+$(if($Latest){$Latest.LastWriteTime}else{'none'}));Write-Host ('last_completed_unit: '+$(if($Progress){$Progress|ConvertTo-Json -Compress}else{'none'}));if($Progress -and $Progress.stage -eq 'build_corrected_camera_compensated_memory' -and (Test-Path $State.stdout)){$Sequences=(Get-Content $State.stdout|Select-String '"kind": "online_action_bank_sequence"').Count;Write-Host "action_memory_sequences: $Sequences/172"};$Gpu=& nvidia-smi --query-gpu=utilization.gpu,memory.used --format=csv,noheader,nounits 2>$null;Write-Host "gpu_signal: $Gpu";Write-Host "stdout: $($State.stdout)";Write-Host "stderr: $($State.stderr)"
